<?php
require_once 'config.php';require_login();$pageTitle='Catat Pelanggaran';$error='';if($_SERVER['REQUEST_METHOD']==='POST'){$act=$_POST['action']??'';if($act==='save'){$sid=(int)($_POST['id_siswa']??0);$jid=(int)($_POST['id_jenis']??0);$tgl=str_replace('T',' ',$_POST['tanggal']??'');$ket=trim($_POST['keterangan']??'');if(!$sid||!$jid||!$tgl)$error='Siswa, jenis, dan tanggal wajib diisi.';else{$st=$pdo->prepare('INSERT INTO pelanggaran(id_siswa,id_jenis,tanggal,keterangan) VALUES(?,?,?,?)');$st->execute([$sid,$jid,$tgl,$ket]);header('Location: pelanggaran.php?ok=1');exit;}}if($act==='status'){$status=$_POST['status']??'Baru';if(!in_array($status,['Baru','Diproses','Selesai'],true))$status='Baru';$st=$pdo->prepare('UPDATE pelanggaran SET status=? WHERE id_pelanggaran=?');$st->execute([$status,(int)$_POST['id_pelanggaran']]);header('Location: pelanggaran.php?ok=1');exit;}}
$siswa=$pdo->query('SELECT id_siswa,nis,nama_siswa,kelas FROM siswa ORDER BY nama_siswa')->fetchAll();$jenis=$pdo->query('SELECT * FROM jenis_pelanggaran ORDER BY nama_jenis')->fetchAll();$q=trim($_GET['q']??'');$st=$pdo->prepare('SELECT p.*,s.nis,s.nama_siswa,s.kelas,j.nama_jenis,j.poin FROM pelanggaran p JOIN siswa s ON s.id_siswa=p.id_siswa JOIN jenis_pelanggaran j ON j.id_jenis=p.id_jenis WHERE s.nama_siswa LIKE ? OR s.nis LIKE ? OR s.kelas LIKE ? ORDER BY p.tanggal DESC');$like="%$q%";$st->execute([$like,$like,$like]);$rows=$st->fetchAll();include 'partials/header.php';?>
<?php if($error):?><div class="alert error"><?=e($error)?></div><?php endif;?><?php if(isset($_GET['ok'])):?><div class="alert success">Catatan berhasil disimpan/diperbarui.</div><?php endif;?><div class="panel"><div class="panel-head"><div><h3>Input Pelanggaran Baru</h3><p>Catat kejadian dengan jelas dan objektif.</p></div></div><?php if(!$siswa||!$jenis):?><div class="alert warning">Tambahkan minimal satu siswa dan satu jenis pelanggaran terlebih dahulu.</div><?php endif;?><form method="post" class="form-grid"><input type="hidden" name="action" value="save"><div class="wide"><label>Nama Siswa *</label><select name="id_siswa" required><option value="">Pilih siswa</option><?php foreach($siswa as $s):?><option value="<?=$s['id_siswa']?>"><?=e($s['nis'].' — '.$s['nama_siswa'].' ('.$s['kelas'].')')?></option><?php endforeach;?></select></div><div><label>Jenis Pelanggaran *</label><select name="id_jenis" required><option value="">Pilih jenis</option><?php foreach($jenis as $j):?><option value="<?=$j['id_jenis']?>"><?=e($j['nama_jenis'].' — '.$j['poin'].' poin')?></option><?php endforeach;?></select></div><div><label>Tanggal dan Waktu *</label><input type="datetime-local" name="tanggal" required value="<?=date('Y-m-d\TH:i')?>"></div><div class="wide"><label>Keterangan / Kronologi</label><textarea name="keterangan" rows="3" placeholder="Tuliskan kronologi singkat..."></textarea></div><div class="wide"><button class="btn primary" <?=(!$siswa||!$jenis)?'disabled':''?>>Simpan Pelanggaran</button></div></form></div><div class="panel"><div class="panel-head"><div><h3>Riwayat Pelanggaran (<?=count($rows)?>)</h3><p>Ubah status tindak lanjut sesuai perkembangan.</p></div><form method="get" class="search"><input name="q" value="<?=e($q)?>" placeholder="Cari siswa atau kelas"><button class="btn">Cari</button></form></div><div class="table-wrap"><table><thead><tr><th>Tanggal</th><th>Siswa</th><th>Kelas</th><th>Jenis</th><th>Poin</th><th>Keterangan</th><th>Status</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e(date('d/m/Y H:i',strtotime($r['tanggal'])))?></td><td><b><?=e($r['nama_siswa'])?></b><small class="subline"><?=e($r['nis'])?></small></td><td><?=e($r['kelas'])?></td><td><?=e($r['nama_jenis'])?></td><td><?=$r['poin']?></td><td><?=e($r['keterangan'])?></td><td><form method="post"><input type="hidden" name="action" value="status"><input type="hidden" name="id_pelanggaran" value="<?=$r['id_pelanggaran']?>"><select name="status" onchange="this.form.submit()" class="status-select"><?php foreach(['Baru','Diproses','Selesai'] as $v):?><option <?=$r['status']===$v?'selected':''?>><?=e($v)?></option><?php endforeach;?></select></form></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="7" class="empty">Belum ada catatan pelanggaran.</td></tr><?php endif;?></tbody></table></div></div><?php include 'partials/footer.php';?>
